import React from 'react'
import { useAuth0 } from '@auth0/auth0-react';

import LoginButton from '../../components/page/login/LoginButton';

const Login = () => {
    const { isAuthenticated } = useAuth0();
  
    return (
        !isAuthenticated && 
        <>
            <div>Sign In</div>
            <LoginButton/>
        </>
    )
}

export default Login
